# One change: ranged kiting. A ranged champion with a visible enemy adjacent steps away first (move_away_from),
# then shoots from range, instead of trading blows in place with a melee diver.

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

