# style-h3 [style-h line]: builds on style-h2 (stun opener first, engage priority, resets after a basic,
# team-target focus). Two changes:
# 1) Kiting: a ranged champion with its target adjacent casts its abilities, then steps away
#    (move_away_from) instead of trading in place. If it is cornered and the step fails, it still attacks.
#    A ranged move and attack share one allowance, so the step costs that turn's basic attack but keeps
#    the champion at range for the following turns.
# 2) Long approach dashes inside hunt() sit behind a fuel_remaining() gate again (100x100 safety).

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

def hunt(u):
    set_team_target(u)
    set_priority(200)
    if ability_ready(0) and slot_stun(0) > 0 and distance( position(), unit_position(u) ) <= slot_range(0) + slot_radius(0):
        if slot_is_dash(0):
            dash_towards(0, unit_position(u))
        elif slot_is_aoe(0):
            cast_at_tile(0, unit_position(u))
        else:
            cast_at_unit(0, u)
    if ability_ready(1) and slot_stun(1) > 0 and distance( position(), unit_position(u) ) <= slot_range(1) + slot_radius(1):
        if slot_is_dash(1):
            dash_towards(1, unit_position(u))
        elif slot_is_aoe(1):
            cast_at_tile(1, unit_position(u))
