            move_towards( unit_position(u) )
        end_turn()
    if fuel_remaining() > 55000 and distance( unit_position(u), position() ) > 1 + 1 and ability_ready(0) and slot_is_dash(0):
        dash_towards(0, unit_position(u))
    if fuel_remaining() > 55000 and distance( unit_position(u), position() ) > 1 + 1 and ability_ready(1) and slot_is_dash(1):
