# hunter v6 [line: style]: builds on hunter v5. One change: team focus fire inside reach. Before the
# weakest-in-reach rule, if the team target is already inside our attack reach (1 tile melee, 3 ranged)
# and not on its own spawn, hit it. Allies that name the same target then converge on it in the same
# round. Everything else (stun opener, retreat, tribute, camp farming) is unchanged from v5.

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
            cast_self(slot)
        elif not slot_is_dash(slot):
            cast_at_unit(slot, u)

def dash_to(slot, t):
    if ability_ready(slot):
        if slot_is_dash(slot):
            dash_towards(slot, t)

# stun opener: a ready, non-dash stun cast at a unit within its cast range
def opener(slot, u):
    if ability_ready(slot) and slot_stun(slot) > 0 and not slot_is_dash(slot):
        if distance( unit_position(u), position() ) <= slot_range(slot):
            cast_at_unit(slot, u)

