# the ability's full reach (slot_stun > 0 and within slot_range + slot_radius) before closing in, so the
# first hit lands on the turn we arrive. Everything else is unchanged from version 1.

def cast_on(slot, u):
    if ability_ready(slot):
        if slot_is_shield(slot) or slot_is_heal(slot):
